int compute_flushbits ( const lame_internal_flags * gfc , int * total_bytes_output ) { SessionConfig_t const * const cfg = & gfc -> cfg ; EncStateVar_t const * const esv = & gfc -> sv_enc ; int flushbits , remaining_headers ; int bitsPerFrame ; int last_ptr , first_ptr ; first_ptr = esv -> w_ptr ; last_ptr = esv -> h_ptr - 1 ; if ( last_ptr == - 1 ) { last_ptr = MAX_HEADER_BUF - 1 ; } flushbits = esv -> header [ last_ptr ] . write_timing - gfc -> bs . totbit ; * total_bytes_output = flushbits ; if ( flushbits >= 0 ) { remaining_headers = 1 + last_ptr - first_ptr ; if ( last_ptr < first_ptr ) { remaining_headers = 1 + last_ptr - first_ptr + MAX_HEADER_BUF ; } flushbits -= remaining_headers * 8 * cfg -> sideinfo_len ; } bitsPerFrame = getframebits ( gfc , NULL ) ; flushbits += bitsPerFrame ; * total_bytes_output += bitsPerFrame ; if ( * total_bytes_output % 8 ) { * total_bytes_output = 1 + ( * total_bytes_output / 8 ) ; } else { * total_bytes_output = ( * total_bytes_output / 8 ) ; } * total_bytes_output += gfc -> bs . buf_byte_idx + 1 ; if ( flushbits < 0 ) { DEBUGF ( gfc , "last header write_timing = %i \n" , esv -> header [ last_ptr ] . write_timing ) ; DEBUGF ( gfc , "first header write_timing = %i \n" , esv -> header [ first_ptr ] . write_timing ) ; DEBUGF ( gfc , "bs.totbit:                 %i \n" , gfc -> bs . totbit ) ; DEBUGF ( gfc , "first_ptr, last_ptr        %i %i \n" , first_ptr , last_ptr ) ; DEBUGF ( gfc , "remaining_headers =        %i \n" , remaining_headers ) ; DEBUGF ( gfc , "bitsperframe:              %i \n" , bitsPerFrame ) ; DEBUGF ( gfc , "sidelen:                   %i \n" , cfg -> sideinfo_len ) ; ERRORF ( gfc , "strange error flushing buffer ... \n" ) ; } return flushbits ; } 